export type Setting = {
	/**  e.g. `agents.grouping`, `updates.channel` */
	key: string,
	/**  `user` or `repo:<owner>/<name>` */
	scope: string,
	value: unknown,
};

export type Severity = "info" | "warn" | "high";

export type Sha = string;

/**  What "ship" does (docs/spaces.md §1, §12). */
export type ShipAction =
/**  Host project: squash, push the branch, open a ready PR. */
"open_pr" |
/**  Same, as a draft. */
"open_draft_pr" |
/**  The space has a PR: push the turns since as one new commit. */
"push" |
/**  Local folder: merge into its checked-out branch. */
"merge_locally" |
/**  Local folder: write the branch only. */
"keep_branch";

/**  How a space was shipped (docs/spaces.md §1). */
export type ShipKind =
/**  Pushed to the host; `Space::pr` is (or is about to be) its PR. */
"pr" |
/**  Merged into a local folder's checked-out branch. */
"merged_locally" |
/**  Written as a branch in a local folder. */
"branch";

export type ShipSpaceRequest = {
	space: string,
	action: ShipAction,
	/**
	 *  Commit message / PR title; defaults to the goal's first line (Push:
	 *  the latest message since the last push).
	 */
	title?: string | null,
};

export type Side = "old" | "new";

export type SkillBody = {
	info: SkillInfo,
	/**  Full SKILL.md text (front matter included). */
	body: string,
	editable: boolean,
};

export type SkillId = string;

export type SkillInfo = {
	id: string,
	title: string,
	description: string,
	/**  `built-in`, `~/.claude/skills` or `<owner>/<repo> · .claude/skills` */
	source: string,
};

export type SkillRun = {
	id: string,
	pr: PrId,
	skill: string,
	agents: AgentId[],
	status: RunStatus,
	error: string | null,
	started_at: number,
};

export type SnoozeUntil = { kind: "time"; at: number } | { kind: "next_push" } | { kind: "checks_green" };

/**
 *  Synced row `space`, id = `Space::id`. Core-owned: written only by the
 *  space commands, never by a client transaction.
 */
export type Space = {
	id: string,
	/**  `Project::id` the space belongs to. */
	project: string,
	name: string,
	/**  What the space is for; sent as the first turn. */
	goal: string,
	/**
	 *  Branch name the work is shipped as: `<host login>/<slug>`, or
	 *  `space/<slug>` with no login (a local folder, or offline).
	 */
	branch: string,
	/**  Base branch name, and the commit the space forked from. */
	base: string,
	base_sha: Sha,
	/**  Last checkpoint (`refs/theodore/spaces/<id>`). */
	head_sha: Sha,
	/**  Absolute path of the space's worktree. */
	worktree: string,
	status: SpaceStatus,
	agent: AgentId,
	model?: string | null,
	mode: SpaceMode,
	/**  The branch review (`open_branch` plumbing) the live diff and Review use. */
	review_pr?: PrId | null,
	/**  The host PR, once opened: the link from drafting to review. */
	pr?: PrId | null,
	turns: number,
	/**
	 *  Run id of the turn in flight (`space:<id>:<message>`); its streaming
	 *  text arrives as `Ephemeral::AgentDelta` under this id.
	 */
	run?: string | null,
	error?: string | null,
	/**  The last Open PR / Push / Merge locally / Keep as branch. */
	shipped?: SpaceShipped | null,
	/**
	 *  When the change was done: its PR merged, or it was merged locally /
	 *  kept as a branch. `spaces.auto_archive_days` counts from here.
	 */
	done_at?: number | null,
	/**
	 *  Every turn's checkpoints, oldest first: what "Undo last turn" moves
	 *  back to. Spaces from before it was recorded have none.
	 */
	turn_log?: SpaceTurn[],
	created_at: number,
	updated_at: number,
};

/**
 *  A review comment sent to a space's agent (docs/spaces.md §3): it must
 *  belong to the space's PR or to its own branch review.
 */
export type SpaceFeedback =
/**  A review thread (`Thread::id`), every comment quoted. */
{ kind: "thread"; id: string } |
/**  A draft comment (`Draft::id`). */
{ kind: "draft"; id: string } |
/**  A finding (`Finding::id`). */
{ kind: "finding"; id: string };

export type SpaceFeedbackRequest = {
	space: string,
	items: SpaceFeedback[],
};

/**  What the agent may do in a turn (docs/spaces.md §5). */
export type SpaceMode =
/**  Read, grep, MCP; no writes. */
"ask" |
/**  Edit files inside the space. */
"edit" |
/**
 *  Edit, plus run shell commands (tests, installs) without asking. No
 *  sandbox of Theodore's own: the agent CLI runs as configured.
 */
"run";

export type SpaceReviewRequest = {
	space: string,
	/**  Also group the diff by meaning (Review); `false` for the live diff. */
	group: boolean,
};

export type SpaceSendRequest = {
	space: string,
	text: string,
	/**  Switches the space's agent from this turn on. */
	agent?: AgentId | null,
	model?: string | null,
	mode?: SpaceMode | null,
};

/**  The space's last ship: the squashed commit and where it went. */
export type SpaceShipped = {
	how: ShipKind,
	/**
	 *  Branch it was pushed to / written as (the folder's branch for
	 *  `merged_locally`).
	 */
	branch: string,
	/**
	 *  The squashed commit last pushed or merged
	 *  (`refs/theodore/shipped/<id>`).
	 */
	sha: Sha,
	/**  The checkpoint it was made from: turns after it are "not pushed". */
	head: Sha,
	/**  Pushes to the PR branch so far, the first one included. */
	pushes: number,
	at: number,
};

export type SpaceStatus =
/**  No turn running. */
"idle" | "running" |
/**  The last turn errored, was interrupted, or the worktree is gone. */
"failed" | "archived";

/**
 *  One agent turn of a space: the messages it answered and the checkpoint
 *  it moved the space from and to.
 */
export type SpaceTurn = {
	/**  The `chat_message` id of your message that started it. */
	message: string,
	/**  The `chat_message` id of the agent's reply. */
	reply: string,
	/**  Checkpoint before the turn, and after it (equal when nothing changed). */
	before: Sha,
	after: Sha,
	/**
	 *  Undone: the space went back to `before`; the transcript keeps the
	 *  turn, the next turns' prompts leave it out.
	 */
	undone?: boolean,
};

/**
 *  One PR's place in a same-repo chain of stacked PRs (plan "Stack"): the
 *  parent this PR is based on, and the children based on it. Computed by
 *  `theodore_domain::stack::compute_stacks` from the PR rows already synced
 *  — no extra host call.
 */
export type StackInfo = {
	/**  The PR this one is based on (`head_ref` of that PR == this `base_ref`). */
	base_pr: number | null,
	/**  PRs based on this one (`base_ref` of those PRs == this `head_ref`). */
	children: number[],
};

export type SubmitReviewRequest = {
	pr: PrId,
	event: ReviewEvent,
	body: string,
};

export type SymbolHit = {
	path: string,
	line: number,
	kind: SymbolKind,
	/**  The matched source line, trimmed. */
	preview: string,
};

export type SymbolKind = "definition" | "reference";

export type SyncCode = "I" | "U" | "C" | "A" | "D";

/**
 *  Event `sync`: covers `(from_sync_id, last_sync_id]`. A UI whose own
 *  `lastSyncId < from_sync_id` missed a frame and calls `catch_up`.
 */
export type SyncFrame = {
	from_sync_id: number,
	last_sync_id: number,
	actions: WireAction[],
	/**
	 *  Set on a `catch_up` response whose `since` fell behind the sync
	 *  log's compaction horizon: `actions` is empty and cannot be trusted
	 *  to close the gap — the caller must bootstrap from scratch instead
	 *  of applying this frame incrementally. Always `false` otherwise.
	 */
	resync_required?: boolean,
};

export type Task = {
	id: TaskId,
	pr: PrId,
	title: string,
	body: string,
	anchor: Anchor | null,
	thread: ThreadId | null,
	status: TaskStatus,
	assignee: Assignee,
	fix: Fix | null,
	created_at: number,
	/**
	 *  A push moved the diff out from under this task's anchor (plan §4);
	 *  `None` anchor tasks are never affected.
	 */
	outdated?: boolean,
};

export type TaskDecision = {
	task: TaskId,
	accept: boolean,
	/**  Why a fix was rejected (sent back to the agent on the next attempt). */
	reason: string | null,
};

export type TaskId = string;

export type TaskStatus = "todo" | "progress" |
/**  Agent fix waiting for a human ("To verify"). */
"review" | "done";

export type Thread = {
	id: ThreadId,
	anchor: Anchor | null,
	resolved: boolean,
	outdated: boolean,
	comments: Comment[],
};

export type ThreadId = string;

export type ToastLevel = "info" | "warn" | "error";

export type TokenSource = "keychain" | "gh" | "env" | "none" |
/**  The simulated sandbox host (docs/sandbox.md): no real token at all. */
"sandbox";

export type Transaction = {
	/**  Client-generated, for de-duplication on retry. */
	id: string,
	ops: MutationOp[],
};

export type TransactionResult = { status: "ok"; last_sync_id: number } |
/**  Rejected by domain validation; the UI rolls back. */
{ status: "rejected"; reason: string };

export type TriageAction =
/**  The viewer takes the review themselves. */
{ action: "take" } |
/**  The viewer declines; the inbox row is marked done. */
{ action: "decline" } |
/**  Hand the review to someone else (logins). */
{ action: "reassign"; to: string[] };

export type TriageRequest = {
	pr: PrId,
	action: TriageAction,
};

export type UpdateInfo = {
	version: string,
	notes: string,
	downloaded: boolean,
};

export type ViewedState = "unviewed" | "viewed" |
/**  Was viewed, then the file changed. */
"dismissed";

export type WireAction = {
	id: number,
	model: string,
	model_id: string,
	action: SyncCode,
	data: unknown | null,
};

export type WireRow = {
	model: string,
	id: string,
	data: unknown,
	archived: boolean,
};
